{
  "report": "Resumo executivo (até 2024-05-02): ALUP11 mostra viés baixista no curto/médio prazo. O fechamento em 2024-05-02 foi R$ 28,71 — abaixo das principais médias móveis (MM20 = 29,248; MM50 = 29,9016; MM200 = 29,3413), o que caracteriza pressão de venda. A queda abrupta em abril ampliou a volatilidade (Bandas de Bollinger largas) e gerou um repique no pregão de 02/05 acompanhado por volume excepcionalmente alto. Apesar do rebound, os indicadores técnicos ainda favorecem a manutenção do viés de baixa até confirmação em contrário.",
  "signal": "Baixa",
  "support_levels": [
    27.4,
    27.72,
    26.8598
  ],
  "resistance_levels": [
    29.248,
    29.9016,
    31.5
  ],
  "indicator_readings": [
    {
      "indicator": "Fechamento",
      "reading": "28.71",
      "interpretation": "Preço abaixo das MMs principais; ponto de reversão intradiária, mas ainda em região de fraqueza."
    },
    {
      "indicator": "MM20",
      "reading": "29.2480",
      "interpretation": "Preço (28,71) abaixo da MM20 → viés de curto prazo baixista; atua como primeiro nível de resistência."
    },
    {
      "indicator": "MM50",
      "reading": "29.9016",
      "interpretation": "Preço abaixo da MM50 → viés de médio prazo baixista; MM50 ainda acima da MM200 (estrutura parcialmente mista)."
    },
    {
      "indicator": "MM200",
      "reading": "29.3413",
      "interpretation": "Preço abaixo da MM200 → quebra da referência de longo prazo no preço, sinal de fraqueza até recuperação consistente."
    },
    {
      "indicator": "EMA9",
      "reading": "28.3399",
      "interpretation": "Preço ligeiramente acima da EMA9 → pullback de curtíssimo prazo; não elimina a tendência negativa."
    },
    {
      "indicator": "EMA21",
      "reading": "29.0015",
      "interpretation": "EMA21 acima do preço → resistência de curto prazo; EMA9 < EMA21 confirma estrutura corretiva."
    },
    {
      "indicator": "MACD",
      "reading": "-0.6444",
      "interpretation": "MACD negativo e abaixo da linha de sinal → momentum baixista predominante."
    },
    {
      "indicator": "MACD_signal",
      "reading": "-0.5297",
      "interpretation": "Linha de sinal confirmando tendência negativa; atenção à convergência recente."
    },
    {
      "indicator": "MACD_hist",
      "reading": "-0.1147",
      "interpretation": "Histograma negativo, porém menos negativo que em dias anteriores → desaceleração da pressão vendedora; possível rebound de alívio."
    },
    {
      "indicator": "BB_lower",
      "reading": "26.8598",
      "interpretation": "Banda inferior — suporte dinâmico adicional (zona de sobrevenda)."
    },
    {
      "indicator": "BB_mid",
      "reading": "29.2480",
      "interpretation": "Média das Bollinger coincide com MM20 e funciona como resistência imediata."
    },
    {
      "indicator": "BB_upper",
      "reading": "31.6362",
      "interpretation": "Banda superior — resistência/objetivo em caso de recuperação significativa."
    },
    {
      "indicator": "RSI14",
      "reading": "43.8695",
      "interpretation": "RSI saiu da zona de sobrevenda e está neutro (~44); ainda não há confirmação de força compradora sustentada."
    },
    {
      "indicator": "Volume (último pregão)",
      "reading": "21290482700",
      "interpretation": "Volume extremamente elevado no dia 02/05 — confirma intensidade do movimento (capitulação / cobertura de posições). Necessária confirmação de continuidade em dias subsequentes."
    }
  ]
}
